// Category B: no behaviour beyond keeping focus clear of itself. It owns the look a site's top bar
// needs, which a Block may not set: the fill that content scrolls under, the edge that ends it, and
// its place on the sticky layer. Its content stops at the page grid's frame, so a Navbar inside
// lines up with the page below it.
import type { CSSProperties, HTMLAttributes, Ref } from "react";
import { useScrollClearance } from "./useScrollClearance";
import "./SiteHeader.css";

export interface SiteHeaderProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /** Keeps the bar at the top of the viewport while the page scrolls. */
  isSticky?: boolean;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function SiteHeader({ isSticky = true, className, children, ref, ...props }: SiteHeaderProps) {
  // A sticky bar sits over the top of the page, so the document's top scroll padding follows its
  // height while it sticks (a wrapped row on a phone included).
  const clearRef = useScrollClearance("start", ref, isSticky);

  return (
    <header
      {...props}
      ref={clearRef}
      data-sticky={isSticky || undefined}
      className={className ? `sd-site-header ${className}` : "sd-site-header"}
    >
      <div className="sd-site-header__frame">{children}</div>
    </header>
  );
}

/* SiteHeader.css — .sd-site-header (+ __frame)
   A full-width bar on the page's own fill with a decorative edge below. The frame inside takes the
   page grid's margin and cap (token-contract.md: Cmp(site-header) reads `grid` as the page frame),
   so the bar's content starts and stops where the page's does. */
.sd-site-header {
  inline-size: 100%;
  background: var(--sd-site-header-background);
  border-block-end: var(--sd-site-header-border-width) solid var(--sd-site-header-border);
}

.sd-site-header[data-sticky] {
  position: sticky;
  inset-block-start: 0;
  z-index: var(--sd-site-header-z-index);
}

.sd-site-header__frame {
  max-inline-size: var(--sd-site-header-max-width);
  margin-inline: auto;
  padding-inline: var(--sd-site-header-padding-inline);
}
